module lfsr_4bit (
    input        clk,
    input        rst,
    input        en,
    output [3:0] out
);
    reg [3:0] state;
    wire feedback = state[3] ^ state[0];

    always_ff @(posedge clk) begin
        if (rst)
            state <= 4'b0001;
        else if (en)
            state <= {state[2:0], feedback};
    end

    assign out = state;
endmodule

module freq_divider_10 (
    input  clk,
    input  rst,
    output reg div_clk
);
    reg [3:0] counter;
    always_ff @(posedge clk) begin
        if (rst) begin
            counter <= 4'd0;
            div_clk <= 1'b0;
        end else begin
            if (counter == 4'd4) begin
                counter <= 4'd0;
                div_clk <= ~div_clk;
            end else begin
                counter <= counter + 4'd1;
            end
        end
    end
endmodule

