module spi_master (
    input        clk,
    input        rst,
    input        start,
    input  [7:0] data_in,
    output reg   mosi,
    output       sclk,
    output reg   cs_n,
    output reg [7:0] data_out,
    output reg   done
);
    reg [1:0] clk_div;
    reg [2:0] bit_cnt;
    reg [7:0] tx_reg, rx_reg;
    reg       sclk_reg;
    reg       active;

    always_ff @(posedge clk) begin
        if (rst) begin
            clk_div  <= 2'd0;
            sclk_reg <= 1'b0;
            cs_n     <= 1'b1;
            active   <= 1'b0;
            done     <= 1'b0;
            bit_cnt  <= 3'd0;
        end else begin
            done <= 1'b0;
            if (!active && start) begin
                active  <= 1'b1;
                cs_n    <= 1'b0;
                tx_reg  <= data_in;
                bit_cnt <= 3'd0;
                clk_div <= 2'd0;
            end else if (active) begin
                clk_div <= clk_div + 2'd1;
                if (clk_div == 2'd3) begin
                    sclk_reg <= ~sclk_reg;
                    if (!sclk_reg) begin  // rising edge
                        rx_reg <= {rx_reg[6:0], mosi};
                    end else begin        // falling edge
                        mosi <= tx_reg[7];
                        tx_reg <= tx_reg << 1;
                        if (bit_cnt == 3'd7) begin
                            active <= 1'b0;
                            cs_n   <= 1'b1;
                            done   <= 1'b1;
                            data_out <= rx_reg;
                        end else begin
                            bit_cnt <= bit_cnt + 3'd1;
                        end
                    end
                end
            end
        end
    end

    assign sclk = sclk_reg;
endmodule

module shift_register_piso (
    input        clk,
    input        rst,
    input        load,
    input  [3:0] parallel_in,
    output       serial_out
);
    reg [3:0] reg_data;

    always_ff @(posedge clk) begin
        if (rst)
            reg_data <= 4'b0;
        else if (load)
            reg_data <= parallel_in;
        else
            reg_data <= {reg_data[2:0], 1'b0};
    end

    assign serial_out = reg_data[3];
endmodule

module register_file_32x32 (
